import{_ as n,l as i,o as e,c as o,v as t,p as s,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"并购套利","description":"","frontmatter":{"title":"并购套利","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/merger-arb-event.md","filePath":"quant/merger-arb-event.md","lastUpdated":1789023840000}'),h={name:"quant/merger-arb-event.md"};function c(B,a,u,A,_,m){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="并购套利" tabindex="-1">并购套利 <a class="header-anchor" href="#并购套利" aria-label="Permalink to &quot;并购套利&quot;">​</a></h1><div class="epigraph"><p>宣布后的价差不是无风险利润：它补偿交易失败、延迟、融资与借券。用成交价回填宣布前持仓，或忽略失败路径，价差会看起来像 alpha。</p><footer>—— 据 Mitchell and Pulvino, Journal of Finance, 2001；Baker and Savasoglu 对并购套利收益的讨论整理</footer></div><p>上一课<a href="/quant/earnings-event-driven">业绩公告作为事件</a>把财报变成可交易事件。并购是另一类公告：目标价与时间表被写出，价差可观测。本课补并购套利的回测偏差与资金约束，不写反垄断法汇编，不把要约流程做成法务课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mitchell–Pulvino 指出并购套利收益有保险性质：平时收价差，市场下跌时交易失败扎堆、损失非线性。纸面回测常见三错：（1）用事后已完成的交易样本，丢掉失败与撤回——幸存者；（2）在宣布前一日按宣布后价格成交——前视；（3）现金要约当无融资、换股当无借券。缺口是：宇宙为<strong>当时已宣布、尚未完成或失败</strong>的交易，成交从宣布后第一可成交价起，失败路径保留，资金按现金腿与股票腿分别占用。</p><p>财务课的退市在这里变成完成日：成功并购常以退市结束，要用成交对价，而不是把最后交易日价格冻到样本末。</p><h3 id="价差不是无风险利率" tabindex="-1">价差不是无风险利率 <a class="header-anchor" href="#价差不是无风险利率" aria-label="Permalink to &quot;价差不是无风险利率&quot;">​</a></h3><p>价差 / 剩余日历日年化后常高于 \\(r_f\\)，因为它含失败概率与延迟。把年化价差当 alpha 再乘杠杆，忽略失败凸性，会在 2008 一类月份爆仓——保证金与融资课已经预告了这条路径。本课把失败当作缺口强平的事件版本：交易破裂日的跳空，不是平滑收敛到要约价。</p><p><span class="marginnote">换股合并还要空头收购方。收购方股票未必可借，费率可能 special。纸面多目标空收购方假设了无限借券。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宣布日盘后或次日开盘建立：多目标，现金要约融资按回购/融资利率占用；换股则对冲收购方，过可借与借券费。持有至完成、撤回或明确失败。失败以公告日第一可成交价平仓，走缺口。完成按对价结算，注意结算周期：现金到账日不是宣布日。样本必须含后来失败的交易，用当时已宣布集合，不能用「最终完成清单」回填。</p><p>杠杆受保证金与集中度限制：套利组合高度相关，haircut 在压力中上调会强制减仓，恰好发生在价差扩大时。</p>',12)),(e(),s(E,null,{default:r(()=>[d(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%AE%A3%E5%B8%83%E5%90%8E%E7%AC%AC%E4%B8%80%E5%8F%AF%E6%88%90%E4%BA%A4%22%5D%20--%3E%20SPR%5B%22%E6%8C%81%E6%9C%89%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20SPR%20--%3E%20OK%5B%22%E5%AE%8C%E6%88%90%EF%BC%9A%E6%8C%89%E5%AF%B9%E4%BB%B7%22%5D%0A%20%20SPR%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%BC%BA%E5%8F%A3%E5%B9%B3%E4%BB%93%22%5D%0A%20%20DONE%5B%22%E4%BB%85%E5%AE%8C%E6%88%90%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20BIAS%5B%22%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>失败公告当日的跳空，按缺口课成交，不要用破裂前收盘「提前平掉」。现金要约的融资占用贯穿持有期，完成日才按对价与结算日释放。换股比率调整、竞争性报价出现时，更新对冲比率，但只用当时公告，不用最终谁赢了的终局结构回填宣布周。完成清单回填与宣布前成交，是本课两条红线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价差的期望补偿失败与延迟；可交易收益还要减融资、借券、强制减仓。压力中三件事同时发生：失败率上升、融资变贵、价差扩大需要追加保证金。纸面线性收敛回测没有这条螺旋。与业绩事件相比，并购持有期更长、占用更久，资金底的利率项权重大于单日缺口项，但失败日的缺口可以是致命的一跳。</p><p><span class="marginnote">不要在此进入要约收购的限价簿排队。本课只处理事件日历与资金；撮合交给后面 LOB 课。</span></p><p>样本 = 宣布日当时已公开、尚未终止的交易，含后来失败的。开仓价 = 宣布后第一可成交。现金要约计入融资占用；换股计入收购方可借与借券费。失败按破裂公告后缺口平仓；成功按对价与结算日。禁止用完成清单回填，禁止在宣布前一日用要约价成交。压力月单独报告，检查线性收敛假设是否破裂。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不评估反垄断概率模型，不写各国要约规则对照表。下一课<a href="/quant/index-rebalance">指数调入调出</a>是另一类日历，被动资金流替代失败风险。后课默认：并购套利样本含失败；开仓在宣布后可成交价；换股空头过借券账单。</p><p>后课指数事件没有「失败要约」，但有生效日买不到。本课失败路径必须留在样本。宣布前成交与完成清单回填是两条禁止。换股空头过可借。压力月非线性是保险性质，不应当成被「异常值剔除」删掉的坏点。</p><p>后课默认并购样本含失败路径，开仓在宣布后可成交价，换股空头过借券账单。</p><p>竞争性报价会改变价差与对冲比率，但只有公告后才进入状态。用最终赢家的交换比率回填宣布后第一周，等于把后来才知道的结构写成当时可交易的对冲，这是并购版前视。</p><p>压力月的非线性损失留在样本里，当作保险性质，不要当异常值从净值里剔掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宣布后价差补偿失败与延迟，不是无风险利率。</li><li>只用完成交易 = 幸存者；宣布前成交 = 前视。</li><li>失败日按缺口平仓，完成日按对价与结算日。</li><li>换股空头受可借与费率约束。</li><li>压力中失败、融资、保证金同时变差，线性收敛回测没有这条路径。</li><li>出处：Mitchell and Pulvino (2001)；Baker and Savasoglu。</li></ul>',13))])}const q=n(h,[["render",c]]);export{b as __pageData,q as default};
